import { BindingMode } from '@antimatterjs/react';
import { getTheme } from '@fluentui/react';
import * as React from 'react';

import { FrameworkElement, IFrameworkElementState } from '../FrameworkElement';
import { Panel } from './Panel';
import { ISelectableItemProps, ISelectableItemState, ISelectorProps, ISelectorState, Selector } from './Primitives/Selector';

export interface IListBoxProps extends ISelectorProps
{
}

export interface IListBoxState extends ISelectorState
{
}

export class ListBox extends Selector<IListBoxProps, IListBoxState>
{
    public static DefaultBindings = {
        ItemsSource: {
            NotifyCollectionChanged: true,
            FallbackValue: []
        },
        SelectedItem: {
            Mode: BindingMode.TwoWay
        }
    };

    protected /* override */ GetContainerForItemOverride(): typeof FrameworkElement
    {
        return ListBoxItem;
    }
}

export interface IListBoxItemProps extends ISelectableItemProps
{    
}

interface IListBoxItemState extends ISelectableItemState
{
}

class ListBoxItem<P extends IListBoxItemProps = {}, S extends IListBoxItemState = {}>
    extends Panel<P, S>
{    
    static theme = getTheme();

    protected /* override */ constructClasses()
    {
        return super.constructClasses() +
            (this.props.IsSelected ? "" : "");
    }

    protected /* override */ getCSSStyles() : React.CSSProperties
    {
        let css: React.CSSProperties = super.getCSSStyles();
        css.margin = "0px";
        css.cursor = "pointer";
        if (this.props.IsSelected)
        {
            css.background = this.props.SelectedBackground || ListBoxItem.theme.semanticColors.listItemBackgroundChecked;
            css.color = this.props.SelectedForeground || ListBoxItem.theme.semanticColors.bodyTextChecked;
        }
        
        return css;
    }
}
